<template><main class="flow-page"><section class="flow-card"><span class="tag">身份认证</span><h1>申请专业身份</h1><p class="hint">提交后由平台管理员审核。审核通过前，你仍可正常使用学生空间。</p><form @submit.prevent="submit"><div class="form-item"><label class="form-label" for="role">申请身份</label><select id="role" v-model="form.role" name="role" class="select"><option value="teacher">教师</option><option value="researcher">科研人员</option></select></div><div class="form-item"><label class="form-label" for="org">学校或机构</label><input id="org" v-model.trim="form.organization_name" class="input" required /></div><template v-if="form.role==='teacher'"><div class="form-item"><label class="form-label" for="stage">任教学段</label><input id="stage" v-model.trim="form.teaching_stage" name="teaching_stage" class="input" /></div><div class="form-item"><label class="form-label" for="subject">任教学科</label><input id="subject" v-model.trim="form.subject" class="input" value="数学" /></div><div class="form-item"><label class="form-label" for="staff">工号（选填）</label><input id="staff" v-model.trim="form.staff_or_student_id" class="input" /></div></template><template v-else><div class="form-item"><label class="form-label" for="direction">研究方向</label><input id="direction" v-model.trim="form.research_direction" name="research_direction" class="input" required /></div><div class="form-item"><label class="form-label" for="department">院系</label><input id="department" v-model.trim="form.department" class="input" /></div></template><p v-if="error" class="error">{{error}}</p><button class="btn btn-primary submit" :disabled="loading||!form.organization_name">{{loading?'提交中…':'提交审核'}}</button></form></section></main></template>
<script setup>
import { reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { authApi } from '@/api/auth'
const router=useRouter(),loading=ref(false),error=ref('');const form=reactive({role:'teacher',organization_name:'',department:'',staff_or_student_id:'',teaching_stage:'',subject:'数学',research_direction:''})
async function submit(){if(loading.value)return;loading.value=true;error.value='';try{await authApi.submitRoleApplication(form);router.push('/identity/pending')}catch(e){error.value=e?.message||'提交失败'}finally{loading.value=false}}
</script>
<style scoped>.flow-page{min-height:100vh;display:grid;place-items:center;padding:28px;background:var(--bg)}.flow-card{width:min(620px,100%);background:white;border:1px solid var(--line);border-radius:22px;padding:36px;box-shadow:var(--shadow-md)}h1{margin:12px 0 5px}.hint{color:var(--ink2);margin-bottom:24px}.submit{width:100%;height:44px}.error{color:var(--err);margin-bottom:10px}</style>
